.chat-detail-screen .msg-transfer-card.msg-transfer-success {
  background-color: #A3A3A3 !important; 
}

/* === 2. 底部极细线 === */
.chat-detail-screen .msg-transfer-card::before {
  content: "";
  position: absolute;
  bottom: 24px; left: 12px; right: 12px; height: 1px;
  background-color: rgba(0, 0, 0, 0.08) !important;
  transform: scaleY(0.5); 
  z-index: 1;
}
/* 🌟 已收款状态：细线变成半透明白色 */
.chat-detail-screen .msg-transfer-card.msg-transfer-success::before {
  background-color: rgba(255, 255, 255, 0.4) !important;
}

