}

/* === 4. 左侧贴上全新的信封贴图 (🌟已放大) === */
.chat-detail-screen .msg-transfer-card::after {
  content: "";
  position: absolute;
  top: -4px; left: 10px; 
  width: 65px; height: 65px; /* 👈 从38px放大到了50px */
