  -webkit-text-fill-color: #895A59 !important; 
  font-size: 28px !important;                  /* 👈 字体从 22px 放大到 28px */
  font-weight: 900 !important;                 
  line-height: 1 !important;
  background: transparent !important; 
}
/* 🌟 已收款状态：金额强制变白 */
.chat-detail-screen .msg-transfer-card.msg-transfer-success .msg-transfer-amount,
.chat-detail-screen .msg-transfer-card.msg-transfer-success .msg-transfer-amount * {
  color: #FFFFFF !important;
  -webkit-text-fill-color: #FFFFFF !important;
}

/* === 6. 底部定制：自定义文字 === */
.chat-detail-screen .msg-transfer-status-text {
  position: absolute !important; bottom: 5px !important; left: 14px !important; font-size: 0 !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important; background: transparent !important;
}
.chat-detail-screen .msg-transfer-status-text::after {
  content: "来自熊の小金库" !important; 
  font-size: 11px !important; 
  color: #895C5B !important; 
