.chat-detail-screen .msg-transfer-card.msg-transfer-success .msg-transfer-status-text::after {
  color: #FFFFFF !important;
  -webkit-text-fill-color: #FFFFFF !important;
}

/* === 7. 终极物理清理机：彻底隐藏多余系统垃圾 === */
