}
.chat-detail-screen .msg-transfer-card *:not(.msg-transfer-amount):not(.msg-transfer-amount *):not(.msg-transfer-status-text):not(.msg-transfer-status-text *) {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  font-size: 0 !important;
  letter-spacing: -999px !important;
